import { silverLessons } from '../silver.ts';
import type { LessonExpansion } from '../types.ts';
import { expand } from './intermediate-builder.ts';
const result: Record<string, LessonExpansion> = {};
const add = (slug: string, ...args: Parameters<typeof expand> extends [unknown, ...infer R] ? R : never) => {
  const lesson = silverLessons.find(item => item.id === `usaco-silver-${slug}`);
  if (!lesson) throw new Error(slug);
  result[lesson.id] = expand(lesson, ...args);
};

add('prefix-sums', [
  { title: 'Traducir un enunciado a índices', body: 'Supón que los días de una semana se numeran del 1 al 7. Una consulta del día 2 al 5 incluye cuatro días, pero nuestro arreglo empieza en cero. Puedes convertirla al intervalo [1,5): restar uno solamente al extremo izquierdo. Otra opción es guardar todos los datos desde el índice 1 y usar P[r]−P[l−1]. Las dos convenciones funcionan; mezclarlas no. Dibuja las posiciones como casillas y los prefijos como fronteras entre casillas. P[i] se ubica antes de la casilla i, así que P[0] es la frontera anterior a todos los datos.' },
  { title: 'Por qué una resta contesta cualquier consulta', body: 'Escribe P[r] = a[0]+…+a[l−1]+a[l]+…+a[r−1] y P[l] = a[0]+…+a[l−1]. Cada término anterior a l aparece una vez con signo positivo y otra con signo negativo. Se cancela sin importar si el dato era positivo, cero o negativo. Esta es una demostración para cualquier arreglo, no solamente una verificación de un ejemplo. También explica por qué el intervalo vacío [l,l) suma cero y por qué no hay que tratar de forma especial las consultas que comienzan en cero.' },
  { title: 'Reconocer qué operaciones se pueden deshacer', body: 'La suma tiene una operación inversa, la resta. El XOR también: si X[i] reúne el XOR de los primeros i elementos, el XOR de [l,r) es X[r] XOR X[l]. En cambio, conocer los mínimos de dos prefijos no permite recuperar el mínimo del intervalo intermedio. Los arreglos [1,8,4] y [1,2,4] tienen los mismos mínimos de prefijos, pero el mínimo de [1,3) es distinto. Para máximos y mínimos necesitarás otra estructura. No memorices «todo rango se resuelve con prefijos»; pregunta qué información se conserva y cómo retirar lo anterior.' },
  { title: 'De contar objetos a sumar indicadores', body: 'Para contar días lluviosos, transforma cada día en 1 si llovió y 0 en caso contrario. La suma de un intervalo se convierte en la cantidad de días lluviosos. Puedes hacer lo mismo con letras vocales, números pares o valores mayores que un umbral fijo. Si n y q llegan a 200000, recorrer cada consulta puede requerir 40000000000 operaciones; prefijos requieren unas 400000. Con valores de magnitud hasta 1000000000, una suma puede alcanzar 200000000000000: necesitas long long desde la lectura y la construcción, no solamente al imprimir.' },
], {
  title: 'Detecta una fórmula que parece funcionar', prompt: 'Para a = [4,−3,6,2], construye P. Una compañera responde [l,r) con P[r−1]−P[l]. Encuentra una consulta no vacía que demuestre el error y explica qué elemento pierde. Después cuenta los valores positivos de [1,4) usando un arreglo indicador.', hints: ['P tiene cinco entradas, empezando por cero.', 'La frontera derecha está después de la última casilla incluida.'], solution: 'P = [0,4,1,7,9]. Para [1,4), la suma correcta es 9−4 = 5. La fórmula propuesta obtiene 7−4 = 3 porque excluye a[3]=2. El indicador de positividad es [1,0,1,1]; sus prefijos son [0,1,1,2,3]. En [1,4) hay 3−1 = 2 valores positivos. Transformar datos cambia qué estás contando, pero conserva la misma fórmula de consulta.'
}, {
  title: 'Balance de entrenamiento', prompt: 'Lee n y q, luego n balances enteros y q consultas l r. Cada consulta pide la suma de los índices l,…,r−1; los índices empiezan en 0. Imprime una respuesta por línea. Límites: 1 ≤ n,q ≤ 200000, |a[i]| ≤ 1000000000 y 0 ≤ l ≤ r ≤ n. Se permiten intervalos vacíos y balances negativos.', hints: ['Guarda n+1 sumas, con la primera igual a cero.', 'No recorras el intervalo de cada pregunta.'], solution: 'Construimos P[i+1]=P[i]+a[i] una sola vez. La respuesta P[r]−P[l] cancela exactamente las posiciones anteriores a l. El arreglo queda fijo entre consultas, condición necesaria para reutilizarlo. La construcción cuesta O(n), las q consultas O(q) y usamos O(n) memoria. En el ejemplo, [1,4) contiene −3,6,2 y suma 5; [2,2) es vacío.', tests: [{input:'4 4\n4 -3 6 2\n0 4\n1 4\n2 2\n0 1\n',output:'9\n5\n0\n4\n'},{input:'1 2\n-7\n0 1\n1 1\n',output:'-7\n0\n'},{input:'3 1\n1000000000 1000000000 1000000000\n0 3\n',output:'3000000000\n'}]
});

add('more-prefix-sums', [
 {title:'Construir una tabla sin memorizar signos',body:'Usa índices desde 1 para los datos y deja la fila 0 y la columna 0 con ceros. Para la celda (i,j), el rectángulo de arriba y el rectángulo de la izquierda cubren lo que queremos salvo la celda nueva; además cubren dos veces su intersección. Por eso P[i][j]=P[i−1][j]+P[i][j−1]−P[i−1][j−1]+a[i][j]. En [[1,2],[3,4]], las entradas interiores de P son [[1,3],[4,10]]. Cada referencia usada pertenece a una fila anterior o a una columna anterior, de modo que construir por filas respeta todas las dependencias.'},
 {title:'Una consulta rectangular completa',body:'Para la matriz [[1,2,3],[4,5,6],[7,8,9]], la tabla interior de prefijos es [[1,3,6],[5,12,21],[12,27,45]]. Queremos filas 2 a 3 y columnas 2 a 3, ambas inclusivas. Empezamos con 45, retiramos las primeras filas: −6; retiramos las primeras columnas: −12; y devolvemos la esquina retirada dos veces: +1. Obtenemos 28, que coincide con 5+6+8+9. La consulta de una celda usa la misma fórmula. Antes de programar, dibuja los cuatro rectángulos y revisa cuál se suma o se resta.'},
 {title:'Diferencias como operación inversa',body:'Si ya existe un arreglo a, define d[0]=a[0] y d[i]=a[i]−a[i−1]. Al acumular d recuperas a porque los términos se cancelan. Ahora una suma sobre [l,r) solamente cambia dos diferencias: la de entrada l y la de salida r. Reserva n+1 posiciones para poder marcar r=n. En dos dimensiones, añadir x a un rectángulo semiabierto requiere cuatro marcas: +x en su esquina superior izquierda y su esquina inferior derecha, −x en las otras dos. Dos acumulaciones, una por eje, reconstruyen los valores finales.'},
 {title:'Cuándo conviene cada representación',body:'Los prefijos responden muchas preguntas sobre datos que ya no cambian. Las diferencias acumulan muchos cambios cuando basta conocer el resultado al final. Por ejemplo, registrar inscripciones de grupos por intervalo de fechas encaja con diferencias; consultar asistencia de rangos históricos encaja con prefijos. Si las actualizaciones y consultas llegan intercaladas y cada consulta debe ver los cambios previos, reconstruir toda la tabla cada vez puede ser demasiado costoso. En una matriz de 2000×2000, una tabla de long long ocupa aproximadamente 32 MB: calcula memoria además de tiempo.'},
],{title:'Dos actualizaciones, una reconstrucción',prompt:'Parte de [1,1,1,1,1]. Agrega 3 a [0,3) y resta 2 a [2,5). Escribe las marcas en un arreglo de diferencias de longitud 6 y el arreglo final. Explica por qué marcar la resta final en r−1 da un resultado equivocado.',hints:['Construye primero diferencias del arreglo inicial.', 'La modificación debe dejar de estar activa exactamente en r.'],solution:'Las diferencias iniciales son [1,0,0,0,0,0]. Las marcas agregan +3 en 0 y −3 en 3; agregan −2 en 2 y +2 en 5. Queda [4,0,−2,−3,0,2]. Acumulando las primeras cinco posiciones obtenemos [4,4,2,−1,−1]. La sexta posición es centinela y no pertenece al resultado. Poner la salida en r−1 cancelaría el cambio una posición antes, dejando sin modificar el último elemento del intervalo.'}, {
 title:'Riego por rectángulos',prompt:'Lee n,m,q, una matriz de n filas y m columnas y q consultas r1 c1 r2 c2. Las coordenadas empiezan en 1 y ambas esquinas están incluidas. Imprime la suma de cada rectángulo. Límites: 1 ≤ n,m ≤ 700; 1 ≤ q ≤ 200000; |a[i][j]| ≤ 1000000; 1 ≤ r1 ≤ r2 ≤ n y 1 ≤ c1 ≤ c2 ≤ m.',hints:['Añade una fila y una columna de ceros.', 'La esquina superior izquierda del prefijo que devuelves termina en r1−1,c1−1.'],solution:'Construimos P con inclusión y exclusión. Cada consulta es P[r2][c2]−P[r1−1][c2]−P[r2][c1−1]+P[r1−1][c1−1]. La esquina compartida requiere el signo positivo para que no desaparezca dos veces. El programa tarda O(nm+q) y ocupa O(nm). Los acumulados se guardan en 64 bits porque pueden superar el rango de int.',code:"#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, m, q;\n    cin >> n >> m >> q;\n    vector<vector<long long>> p(n + 1, vector<long long>(m + 1));\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++) {\n            long long x;\n            cin >> x;\n            p[i][j] = x + p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1];\n        }\n    while (q--) {\n        int a, b, c, d;\n        cin >> a >> b >> c >> d;\n        cout << p[c][d] - p[a - 1][d] - p[c][b - 1] + p[a - 1][b - 1] << \"\\n\";\n    }\n}",tests:[{input:'3 3 2\n1 2 3\n4 5 6\n7 8 9\n2 2 3 3\n1 1 3 3\n',output:'28\n45\n'},{input:'1 1 1\n-6\n1 1 1 1\n',output:'-6\n'},{input:'2 3 2\n0 1 0\n2 -1 4\n1 2 2 2\n2 1 2 3\n',output:'0\n5\n'}]
});

add('two-pointers',[
 {title:'Qué significa conservar una ventana',body:'Una ventana [l,r] es un intervalo contiguo; no puedes saltar un valor interior. Antes de agregar a[r], suma representa los valores desde l hasta r−1. Después de agregarlo, quitamos elementos desde la izquierda mientras la suma exceda K. Al terminar, [l,r] es válida y l es la primera frontera que todavía podemos conservar. Si l=r+1 la ventana está vacía y su longitud es cero. Esta posibilidad es necesaria cuando el elemento nuevo es mayor que K; no inventes una ventana válida de longitud uno.'},
 {title:'Traza que incluye reducciones múltiples',body:'Con [1,2,1,4,1] y K=4, las ventanas válidas después de cada inserción son [1], [1,2], [1,2,1], [4] y [1]. En el cuarto paso la suma salta de 4 a 8: retirar 1 deja 7, retirar 2 deja 5 y retirar 1 deja 4. Hacen falta tres movimientos del extremo izquierdo en esa vuelta, pero esos elementos nunca regresan. La mejor longitud fue 3. Este ejemplo aclara por qué reducir una sola vez con if es incorrecto: necesitas while hasta restablecer la condición.'},
 {title:'Otros dos apuntadores: parejas ordenadas',body:'Para encontrar dos valores distintos que sumen T en un arreglo ordenado, coloca l al inicio y r al final. Si a[l]+a[r]<T, ninguna pareja que conserve l y use un índice hasta r puede alcanzar T; aumenta l. Si la suma es mayor, ninguna pareja que conserve r y use un índice desde l puede servir; disminuye r. Si es igual, encontraste una respuesta. Ordenar cuesta O(n log n); el recorrido posterior es O(n). Guarda los índices originales antes de ordenar si el problema pide posiciones y no solamente valores.'},
 {title:'Contar ventanas en lugar de buscar la más larga',body:'Con elementos no negativos, después de ajustar la ventana hasta que su suma sea a lo sumo K, todos los intervalos que terminan en r y empiezan entre l y r también son válidos. Hay r−l+1. Sumar ese número para cada r cuenta todos los intervalos válidos una sola vez. Esto permite contar intervalos con suma exactamente K mediante «a lo sumo K» menos «a lo sumo K−1», manejando K=0 aparte. Si hay negativos, esa propiedad deja de estar garantizada; los prefijos con una tabla de frecuencias resuelven otro modelo más general.'},
],{title:'La condición que autoriza descartar',prompt:'Una solución descarta el primer valor apenas la suma supera K. Explica por qué falla con [6,−5,2] y K=3. Luego calcula cuántos subarreglos de [1,0,2] tienen suma a lo sumo 2.',hints:['Una extensión futura puede reducir una suma si hay negativos.', 'Cuenta por extremo derecho para no repetir intervalos.'],solution:'Al ver 6, el método lo quita. Pero el arreglo completo suma 3 y tiene longitud 3, por lo que acaba de perder una respuesta óptima. En [1,0,2], terminando en 0 hay un intervalo válido: [1]. Terminando en 1 hay dos: [0] y [1,0]. Terminando en 2 hay dos: [2] y [0,2]; [1,0,2] suma 3. El total es 1+2+2=5. La ausencia de negativos es lo que asegura que cada inicio descartado seguirá siendo inútil.'},{title:'Sesiones dentro del presupuesto',prompt:'Lee n,K y n duraciones no negativas. Imprime la mayor cantidad de sesiones consecutivas cuya duración total no supera K. Puedes escoger ninguna sesión. Límites: 1 ≤ n ≤ 200000; 0 ≤ K ≤ 100000000000000; 0 ≤ a[i] ≤ 1000000000.',hints:['Mantén la suma de la ventana actual.', 'Quita todas las sesiones necesarias, no solo una.'],solution:'El extremo derecho incorpora cada sesión. Mientras la suma supera K retiramos por la izquierda. La monotonía de la suma con datos no negativos garantiza que ningún inicio retirado podrá dar una ventana válida al seguir ampliando. Actualizamos la mayor longitud después de reducir. Ambos extremos avanzan a lo sumo n veces, así que el costo total es O(n), aunque haya ciclos anidados.',tests:[{input:'5 4\n1 2 1 4 1\n',output:'3\n'},{input:'3 0\n0 0 0\n',output:'3\n'},{input:'2 1\n5 6\n',output:'0\n'}]});

add('binary-search-sorted-array',[
 {title:'Antes de buscar, formula una frontera',body:'Buscar «algún 3» deja dudas cuando hay repetidos. Buscar «la primera posición con valor al menos 3» define una respuesta única, incluso si no hay treses. Considera también n como una posición ficticia que satisface el predicado; significa que ningún elemento real sirve. Al inicio l=0,r=n. Mantén dos afirmaciones: toda posición menor que l es demasiado pequeña y toda posición desde r, si es real, ya cumple. No necesitas que la respuesta se encuentre en una casilla real para que el razonamiento funcione.'},
 {title:'Traza con huecos y con repetidos',body:'Busca 6 en [2,4,4,7,9]. Inicialmente [l,r)=[0,5); m=2 y a[2]=4<6, por lo que l=3. Después m=4 y a[4]=9≥6, así que r=4. Luego m=3 y a[3]=7≥6, así que r=3. Termina en 3: es el lugar de inserción de 6. Para buscar la primera posición mayor que x, cambia únicamente la condición de descarte a a[m]≤x. No cambies también los límites ni agregues un ajuste final; eso mezclaría dos invariantes distintos.'},
 {title:'Usar las funciones de la biblioteca',body:'lower_bound(a.begin(),a.end(),x) encuentra el primer elemento no menor que x. upper_bound encuentra el primero mayor. Devuelven iteradores, no índices: resta a.begin() si necesitas una posición. Para contar valores entre L y R incluidos, resta upper_bound(R)−lower_bound(L). Sobre un vector el número de comparaciones y los movimientos son O(log n). En un set usa su método s.lower_bound(x): llamar a la función genérica sobre iteradores que no tienen acceso aleatorio puede requerir muchos movimientos aunque haga pocas comparaciones.'},
 {title:'Demostrar terminación y revisar tamaños',body:'Cuando l<r, m=l+(r−l)/2 cumple l≤m<r. La actualización l=m+1 aumenta estrictamente l; la actualización r=m disminuye estrictamente r. Por ello nunca repetimos el mismo intervalo. Su longitud se divide aproximadamente a la mitad, así que 200000 valores requieren menos de 19 decisiones. Escribe la expresión del centro con una resta para evitar desbordar l+r. La búsqueda no verifica por ti que el arreglo esté ordenado: [1,9,3] puede producir una respuesta incorrecta sin que el programa lance ningún error.'},
],{title:'Tres preguntas, dos fronteras',prompt:'En [1,2,2,2,5,8], calcula lower_bound(2), upper_bound(2), lower_bound(4), y cuántos elementos hay en [2,5]. Da índices desde cero. ¿Se puede usar a[lower_bound(10)] directamente?',hints:['Dibuja una frontera antes del primer 2 y otra después del último.', 'El resultado puede ser igual al tamaño.'],solution:'Las posiciones son 1,4 y 4, respectivamente. Los elementos en [2,5] son tres doses y un cinco: upper_bound(5)−lower_bound(2)=5−1=4. lower_bound(10) devuelve 6, que es el tamaño, así que a[6] queda fuera del vector. Primero se comprueba índice<n; solamente después puede leerse el valor para verificar igualdad. La frontera sirve para contar e insertar aunque no exista el elemento buscado.'},{title:'Primer equipo suficientemente rápido',prompt:'Lee n,x y una lista ordenada no decrecientemente de n enteros. Imprime el primer índice cuyo valor sea al menos x; imprime n si no existe. Los índices empiezan en cero. Límites: 0 ≤ n ≤ 200000 y |x|,|a[i]| ≤ 1000000000. El arreglo vacío es válido.',hints:['La posición n es una respuesta legal.', 'Cuando el centro ya cumple, no lo descartes: puede ser el primero.'],solution:'Conservamos el intervalo [l,r) de decisiones pendientes. Si a[m]<x, descartamos hasta m inclusive; si no, conservamos m como frontera superior. Al terminar l=r y ambas condiciones del invariante obligan a que esa posición sea la primera que sirve. Usamos O(log n) tiempo para buscar y O(1) memoria adicional al arreglo.',tests:[{input:'5 6\n2 4 4 7 9\n',output:'3\n'},{input:'0 3\n',output:'0\n'},{input:'4 2\n2 2 2 2\n',output:'0\n'},{input:'2 9\n1 8\n',output:'2\n'}]});

add('binary-search',[
 {title:'Separar la pregunta de la búsqueda',body:'El predicado posible(C) debe resolver por completo una pregunta más sencilla: «¿Se pueden transportar todos los objetos con a lo sumo k viajes de capacidad C?». Antes de escribir búsqueda binaria, pruébalo con capacidades concretas y compáralo con particiones hechas a mano. Si algún objeto pesa más que C, responde falso de inmediato. Cuenta un primer viaje con carga cero y abre otro únicamente al no caber el siguiente objeto. Todos los pesos son positivos; las fronteras conservan el orden y ningún objeto puede dividirse.'},
 {title:'Probar el recorrido voraz dentro del predicado',body:'Después del primer viaje, el voraz ha transportado el prefijo más largo que cabe. Cualquier otra solución de la misma capacidad llega a una posición igual o anterior. Supón que lo mismo ocurre tras j viajes: en el viaje j+1, el voraz empieza al menos tan adelante y puede cubrir lo que cubra la otra solución sin exceder capacidad. Por inducción, tras cualquier cantidad de viajes nunca lleva menos objetos. Por eso, si el voraz requiere más de k viajes, ninguna partición alternativa puede salvar esa capacidad.'},
 {title:'Trazar la búsqueda exterior',body:'Para [2,3,4,2] con k=2, la capacidad mínima está entre el peso máximo, 4, y la suma, 11. Probamos 7: se puede, así que el límite superior baja a 7. Probamos 5: hacen falta tres viajes, así que el inferior sube a 6. Probamos 6: alcanza y la búsqueda termina. El predicado cambia una sola vez de falso a verdadero porque aumentar capacidad conserva cualquier partición previamente válida. Esta es la propiedad fundamental; la respuesta no tiene que estar guardada en ningún arreglo.'},
 {title:'Otros modelos y costo real',body:'El mismo razonamiento permite minimizar el tiempo para producir una cantidad de objetos con varias máquinas o minimizar la mayor carga al dividir trabajos. Pero cada modelo exige su propio predicado y su propia prueba de monotonía. Para maximizar una distancia mínima, el predicado suele cambiar de verdadero a falso y debes adaptar la frontera con cuidado. En transporte, cada evaluación cuesta O(n) y se realizan O(log S), donde S es la suma de pesos. Guarda S, capacidad y carga en long long. No uses búsqueda binaria sobre «la capacidad es par»: esa condición no es monótona.'},
],{title:'Cuando cambia una regla',prompt:'Con pesos [2,3,4,2] y dos viajes, la respuesta en orden es 6. Si puedes reordenar libremente, ¿baja? ¿Sigue siendo correcto el mismo predicado voraz para todas las entradas? Justifica sin asumir que encontrar un ejemplo basta para demostrarlo.',hints:['La suma total es 11: dos viajes de capacidad 5 solo llevan 10.', 'Prueba [2,2,3,3] con capacidad 5.'],solution:'Para el primer arreglo sigue siendo 6: la suma impide capacidad 5 y existe una partición de capacidad 6. Eso no prueba que el predicado funcione sin orden. En [2,2,3,3], el recorrido consecutivo de capacidad 5 usa [2,2],[3],[3], tres viajes. Reordenando, [2,3] y [2,3] usan dos. La prueba del prefijo más largo dependía de conservar el orden. Al cambiar esa regla cambia el problema y puede cambiar la dificultad.'},{title:'Transporte de computadoras',prompt:'Lee n,k y n pesos positivos. Divide la lista, sin reordenarla, en a lo sumo k bloques consecutivos no vacíos. Imprime la menor capacidad que permite que la suma de cada bloque no la exceda. Límites: 1 ≤ k ≤ n ≤ 200000; 1 ≤ peso ≤ 1000000000.',hints:['La respuesta está entre el máximo y la suma.', 'Una función posible(C) cuenta los bloques necesarios.'],solution:'Para una capacidad dada llenamos cada bloque hasta que el siguiente peso ya no quepa. La prueba del prefijo más largo demuestra que usamos la menor cantidad de bloques posible. Como aumentar la capacidad nunca perjudica, buscamos la primera capacidad posible en [máximo,suma]. El tiempo es O(n log S), memoria O(n), y las sumas usan 64 bits.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<long long> a(n);\n    long long l = 0, r = 0;\n    for (auto &x : a) {\n        cin >> x;\n        l = max(l, x);\n        r += x;\n    }\n    auto ok = [&](long long c) {\n        int grupos = 1;\n        long long carga = 0;\n        for (auto x : a) {\n            if (carga + x > c) {\n                grupos++;\n                carga = 0;\n            }\n            carga += x;\n        }\n        return grupos <= k;\n    };\n    while (l < r) {\n        long long m = l + (r - l) / 2;\n        if (ok(m))\n            r = m;\n        else\n            l = m + 1;\n    }\n    cout << l << \"\\n\";\n}",tests:[{input:'4 2\n2 3 4 2\n',output:'6\n'},{input:'1 1\n9\n',output:'9\n'},{input:'3 1\n1000000000 1000000000 1000000000\n',output:'3000000000\n'},{input:'3 3\n4 1 6\n',output:'6\n'}]});

add('sorting-custom',[
 {title:'El comparador contesta una sola pregunta',body:'Un comparador comp(a,b) devuelve verdadero si a debe colocarse estrictamente antes que b. Nunca debe decir que un objeto va antes que sí mismo. Por eso usar <= es incorrecto: comp(a,a) sería verdadero. Para ordenar concursantes por puntuación descendente y, al empatar, nombre ascendente, compara primero los puntos; solamente si son iguales compara los nombres. No uses «a.puntos>b.puntos o a.nombre<b.nombre» porque mezclaría criterios de prioridad distinta y podría producir contradicciones.'},
 {title:'Un orden coherente y una prueba pequeña',body:'Supón (Ana,7), (Luis,9), (Beto,7). El resultado es Luis, Ana, Beto. Compara por separado cada par y comprueba que, si A va antes que B y B antes que C, A también va antes que C: esto se llama transitividad. Los empates completos pueden quedar en cualquier orden con sort; stable_sort conserva su orden previo. Si necesitas un desempate específico, escríbelo explícitamente. En una competición, un orden no coherente incumple las condiciones de la biblioteca y el resultado deja de estar garantizado; no es simplemente «un orden distinto».'},
 {title:'La compresión conserva el orden, no las distancias',body:'Para coordenadas [1000000000,−7,42,−7], copia y ordena: [−7,−7,42,1000000000]. Elimina duplicados y quedan [−7,42,1000000000]. El rango de cada coordenada es su lower_bound en esta lista: [2,0,1,0]. Ahora puedes usar un arreglo pequeño indexado por rango. Dos valores iguales conservan el mismo rango y una desigualdad se conserva. Pero la distancia entre −7 y 42 era 49 y entre sus rangos es 1: no uses diferencias de rangos para medir longitudes físicas.'},
 {title:'Traducir preguntas sobre coordenadas',body:'Guarda la lista ordenada para convertir un rango de vuelta al valor original. Si vas a consultar valores que no aparecen en los datos, decide si deben incluirse previamente en la compresión o si basta localizar sus fronteras con lower_bound y upper_bound. Por ejemplo, contar puntos con coordenada menor que 50 usa lower_bound(50), aunque 50 no exista. Construir la compresión cuesta O(n log n), buscar cada rango O(log n) y almacenar los valores O(n). La ventaja no es ordenar más rápido, sino hacer posible una estructura posterior cuyo tamaño dependa de n y no de mil millones.'},
],{title:'¿Qué cambia al comprimir?',prompt:'Comprime [20,−10,20,5,100]. Da los rangos desde cero. Una solución afirma que la distancia entre 20 y 100 es 1 porque sus rangos difieren en 1. Explica el error. Diseña además un comparador para pares (puntaje,id) con puntaje mayor primero e id menor como desempate.',hints:['Primero elimina repetidos de la copia ordenada.', 'Dos comparaciones por prioridad se escriben como dos decisiones, no con un OR indiscriminado.'],solution:'Los valores únicos son [−10,5,20,100] y los rangos [2,0,2,1,3]. Se conserva quién es menor y quién es igual, pero no la distancia; 100−20=80. Para comparar: si los puntajes difieren, devuelve a.puntaje>b.puntaje; en otro caso devuelve a.id<b.id. Si los dos campos coinciden, devuelve falso, cumpliendo que un elemento no precede a sí mismo.'},{title:'Coordenadas compactas',prompt:'Lee n y n coordenadas enteras. Imprime en su orden original el rango de cada una entre los valores distintos ordenados, empezando en cero. Límites: 1 ≤ n ≤ 200000; |coordenada| ≤ 1000000000000.',hints:['Ordena una copia para no perder el orden original.', 'unique elimina duplicados consecutivos; borra el sobrante con erase.'],solution:'Copiamos, ordenamos y eliminamos duplicados. Para cada dato original, lower_bound encuentra su posición en la lista única. Así los iguales reciben el mismo rango y las desigualdades se conservan. El costo total es O(n log n), con O(n) memoria. No restamos coordenadas ni reservamos un arreglo tan grande como el mayor valor.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a)\n        cin >> x;\n    auto v = a;\n    sort(v.begin(), v.end());\n    v.erase(unique(v.begin(), v.end()), v.end());\n    for (auto x : a)\n        cout << lower_bound(v.begin(), v.end(), x) - v.begin() << \" \";\n    cout << \"\\n\";\n}",tests:[{input:'5\n20 -10 20 5 100\n',output:'2 0 2 1 3\n'},{input:'1\n1000000000000\n',output:'0\n'},{input:'4\n7 7 7 7\n',output:'0 0 0 0\n'}]});

add('greedy-sorting',[
 {title:'El problema de seleccionar actividades',body:'Cada actividad ocupa [inicio,fin): termina justo cuando otra podría empezar. Quieres asistir a la mayor cantidad sin traslapes; todas valen lo mismo. Ordenar por inicio no basta: una actividad temprana y muy larga puede bloquear muchas cortas. Ordenar por duración tampoco basta: una corta ubicada en medio puede bloquear dos compatibles. La estrategia correcta aquí es elegir la actividad que termina primero entre las disponibles. La palabra «aquí» importa: si cada actividad tiene una recompensa distinta, maximizar cantidad y maximizar recompensa son problemas diferentes.'},
 {title:'Intercambiar sin empeorar',body:'Considera una solución óptima y llama A a su primera actividad. Sea G la que termina más temprano de todas. Si A no es G, reemplázala por G. Como G termina a más tardar que A, todas las actividades que venían después siguen siendo compatibles. La cantidad elegida no disminuye. Por tanto existe una solución óptima que empieza con nuestra elección. Aplicamos exactamente el mismo razonamiento a las actividades que empiezan después de G. Esta repetición demuestra el algoritmo completo; no solo demuestra que la primera elección «se ve conveniente».'},
 {title:'Una ejecución con empates',body:'Para [0,4), [1,2), [2,3), [3,5), [4,6), el orden por final es [1,2), [2,3), [0,4), [3,5), [4,6). Elegimos la primera y recordamos final=2. La segunda empieza en 2, así que es compatible; final=3. Saltamos [0,4), elegimos [3,5) y saltamos [4,6). Obtenemos tres. Entre actividades con el mismo final, cualquiera que sea compatible deja la misma frontera futura. Inicializa esa frontera con un valor menor que todo inicio posible o trata la primera elección por separado.'},
 {title:'Ordenar como herramienta de prueba',body:'Otro patrón consiste en emparejar el menor con el mayor cuando una capacidad lo permite; otro, procesar primero plazos tempranos. Cada patrón usa un argumento diferente. Antes de adoptar una regla, intenta fabricar un caso de tres o cuatro elementos que la rompa. Para actividades con recompensas, [0,2) con valor 1 y [0,3) con valor 100 muestra por qué «terminar primero» ya no maximiza el valor. El costo del algoritmo de cantidad es O(n log n) por ordenar y O(n) por recorrer. No añadas estructuras complicadas cuando basta una frontera.'},
],{title:'Refuta dos reglas tentadoras',prompt:'Para las actividades [0,10), [1,3), [3,5), [5,7), compara elegir primero el inicio más temprano con elegir el final más temprano. Después explica por qué [2,4), [0,3), [3,6) refuta elegir primero la duración más corta.',hints:['Una regla queda refutada con un solo caso donde da menos actividades.', 'Los intervalos que se tocan por una frontera son compatibles.'],solution:'Elegir [0,10) por inicio temprano da una sola actividad; elegir por final da [1,3),[3,5),[5,7), tres. En el segundo ejemplo, [2,4) dura 2 y las otras duran 3; elegir la más corta bloquea ambas y da una. En cambio [0,3) y [3,6) son compatibles y dan dos. Los contraejemplos explican por qué ordenar es parte del algoritmo y necesita una prueba, no una preferencia intuitiva.'},{title:'Agenda de talleres',prompt:'Lee n y n pares inicio fin, con inicio<fin. Puedes escoger talleres cuyos intervalos [inicio,fin) no se traslapen. Imprime la máxima cantidad. Límites: 0 ≤ n ≤ 200000; −1000000000 ≤ inicio<fin ≤ 1000000000. Dos talleres pueden tocarse en su frontera.',hints:['Ordena por final ascendente.', 'Un taller sirve cuando inicio≥último final elegido.'],solution:'El intercambio de la primera actividad por la que termina antes conserva toda la continuación. Tras cada elección queda el mismo problema sobre las actividades posteriores, de modo que el argumento se repite. Recorremos la lista ordenada guardando solamente el último final. El tiempo es O(n log n), con memoria O(n). Para n=0 la respuesta es cero.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <limits>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<pair<long long, long long>> a(n);\n    for (auto &[f, i] : a)\n        cin >> i >> f;\n    sort(a.begin(), a.end());\n    long long fin = numeric_limits<long long>::lowest();\n    int ans = 0;\n    for (auto [f, i] : a)\n        if (i >= fin) {\n            ans++;\n            fin = f;\n        }\n    cout << ans << \"\\n\";\n}",tests:[{input:'5\n0 4\n1 2\n2 3\n3 5\n4 6\n',output:'3\n'},{input:'0\n',output:'0\n'},{input:'3\n-5 -3\n-3 0\n0 2\n',output:'3\n'}]});

add('priority-queues',[
 {title:'Montículo no significa lista ordenada',body:'Una cola de prioridad garantiza acceso rápido al elemento prioritario, pero no permite recorrer todos los datos en orden sin extraerlos. Su representación usual es un árbol binario casi completo guardado en un arreglo: cada padre tiene prioridad al menos tan alta como sus hijos. Por eso la raíz es el mejor elemento. Al insertar, el nuevo elemento sube mientras viole esa propiedad. Al extraer, la última posición ocupa la raíz y baja hasta restaurarla. El árbol tiene altura O(log n), de donde salen los costos de push y pop.'},
 {title:'Qué hace exactamente la biblioteca',body:'priority_queue<int> coloca el mayor arriba. Para tener el menor, usa priority_queue<int,vector<int>,greater<int>>. top consulta y no elimina; pop elimina y no devuelve el elemento. Guarda primero top si lo necesitas. Nunca llames top o pop sobre una cola vacía. Puedes almacenar pares, que se comparan primero por el primer componente y después por el segundo. Para distancias conviene (distancia,vértice); un comparador personalizado puede invertir prioridades, pero debe mantener un orden estricto coherente.'},
 {title:'Combinar datos con un costo acumulado',body:'Supón que fusionar archivos de tamaños a y b cuesta a+b y produce uno de ese tamaño. Con [2,3,8], fusionar 2 y 3 cuesta 5; fusionar 5 y 8 cuesta 13; total 18. Fusionar primero 3 y 8 cuesta 11 y después 13: total 24. Los elementos fusionados temprano vuelven a contribuir en operaciones posteriores. Elegir los dos menores permite colocar los pesos pequeños a mayor profundidad en el árbol de fusiones. Un argumento de intercambio sobre hojas hermanas demuestra que existe un óptimo con los dos menores juntos al fondo.'},
 {title:'Diseñar una simulación con prioridades',body:'En una simulación de eventos, el siguiente evento puede ser el de menor instante. Al procesarlo puedes insertar eventos nuevos: eso impide ordenar una única lista al principio. Si los eventos empatan, define si su orden importa y agrega un desempate. Una cola estándar tampoco elimina eficientemente un elemento arbitrario. A veces puedes marcarlo como obsoleto y descartarlo cuando llegue al frente; ese patrón reaparece en Dijkstra. Para una lista fija que solo quieres ordenar, sort suele ser más sencillo. Usa un montículo cuando las inserciones y extracciones se mezclan.'},
],{title:'Calcula el costo total, no el último',prompt:'Fusiona archivos de tamaños [1,2,3,4] escogiendo siempre los dos menores. Escribe cada costo y el total. ¿Por qué imprimir únicamente el tamaño del archivo final no resuelve el problema?',hints:['Después de fusionar, vuelve a insertar el tamaño combinado.', 'Un dato puede participar en varias fusiones.'],solution:'Se fusionan 1 y 2: costo 3, quedan [3,3,4]. Se fusionan 3 y 3: costo 6, quedan [4,6]. Se fusionan 4 y 6: costo 10. El costo total es 3+6+10=19. El tamaño final es siempre la suma inicial, 10, sin importar el orden; no distingue estrategias. El objetivo suma trabajo repetido, así que necesita un acumulador separado. Con un solo archivo no se hace ninguna fusión y el costo es cero.'},{title:'Fusionar respaldos',prompt:'Lee n tamaños positivos. Repite: escoge dos archivos, paga la suma de sus tamaños y reemplázalos por uno de ese tamaño. Imprime el costo total mínimo para quedar con un archivo. Límites: 1 ≤ n ≤ 200000; 1 ≤ tamaño ≤ 1000000000.',hints:['Necesitas extraer dos mínimos y volver a insertar su suma.', 'Usa long long para tamaños nuevos y para el costo total.'],solution:'Un árbol de fusiones cuenta cada tamaño tantas veces como su profundidad. Intercambiar pesos para que los menores ocupen hojas más profundas nunca aumenta el costo; podemos hacer hermanos a los dos mínimos en una solución óptima y contraerlos. Así la elección de fusionarlos reduce a un problema del mismo tipo. Implementamos esa repetición con un montículo mínimo en O(n log n) tiempo y O(n) memoria.',code:"#include <iostream>\n#include <queue>\n#include <vector>\n#include <functional>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    priority_queue<long long, vector<long long>, greater<long long>> q;\n    while (n--) {\n        long long x;\n        cin >> x;\n        q.push(x);\n    }\n    long long ans = 0;\n    while (q.size() > 1) {\n        auto a = q.top();\n        q.pop();\n        auto b = q.top();\n        q.pop();\n        ans += a + b;\n        q.push(a + b);\n    }\n    cout << ans << \"\\n\";\n}",tests:[{input:'4\n1 2 3 4\n',output:'19\n'},{input:'1\n9\n',output:'0\n'},{input:'3\n1000000000 1000000000 1000000000\n',output:'5000000000\n'}]});

add('graph-traversal',[
 {title:'Construir el modelo sin perder conexiones',body:'Un grafo tiene vértices y aristas. Los vértices pueden representar ciudades, estudiantes o estados de un rompecabezas. En un grafo no dirigido, una arista u−v se guarda en ambas listas de vecinos; en uno dirigido, u→v solamente se guarda desde u. La lista de adyacencia ocupa O(n+m), mientras una matriz ocupa O(n²). Para 200000 vértices, la matriz sería inviable. El enunciado puede numerar desde 1 y el vector desde 0: convierte en la lectura y vuelve a convertir solamente al imprimir identificadores.'},
 {title:'BFS explora por capas',body:'Comienza con un origen en la cola y distancia cero. Al extraer un vértice de distancia d, cada vecino todavía desconocido recibe d+1 y entra al final. Los vértices de distancia d ya estaban antes que los nuevos de distancia d+1. Por ello las capas salen en orden y la primera distancia asignada es mínima en cantidad de aristas. Marca al insertar, no al extraer: si dos vértices descubren al mismo vecino, no queremos encolarlo dos veces. Esta garantía de distancias exige que cada arista cueste lo mismo.'},
 {title:'DFS profundiza y después regresa',body:'DFS toma un vecino pendiente y continúa por él antes de explorar los demás. Puedes implementarla con recursión o una pila explícita. En una cadena de 200000 vértices, la recursión puede agotar la pila del proceso; un vector usado como pila evita ese riesgo. Para solo marcar alcanzables basta una pila de vértices. Para reproducir exactamente los momentos de entrada y salida de la versión recursiva necesitas guardar también qué vecino sigue pendiente. Los dos recorridos detectan la misma componente, aunque visiten sus vértices en distinto orden.'},
 {title:'Un recorrido por cada componente',body:'Si arrancas solamente en el vértice 0, no visitarás componentes desconectadas. Recorre todos los vértices; cuando uno siga sin marcar, incrementa el contador y explora desde él. En una red con aristas 1−2,2−3 y 4−5, más el vértice 6 aislado, hay tres componentes: {1,2,3},{4,5},{6}. Cada vértice entra una vez y cada arista no dirigida se inspecciona dos veces, por eso el costo es O(n+m), incluso con el ciclo exterior. Un grafo dirigido exige distinguir alcanzabilidad, componentes débiles y fuertes: no traslades esta cuenta sin revisar el significado.'},
],{title:'El recorrido y la distancia son cosas distintas',prompt:'En el grafo no dirigido con aristas 1−2,2−3,3−4,1−4 y 5−6, calcula las distancias desde 1 y la cantidad de componentes. Una DFS recorre primero 1,2,3,4: ¿eso demuestra que 4 está a distancia 3?',hints:['La distancia cuenta la ruta más corta, no el orden en que visitaste.', 'Los vértices 5 y 6 no son alcanzables desde 1.'],solution:'Desde 1: d[1]=0,d[2]=1,d[3]=2,d[4]=1; 5 y 6 son inalcanzables. Hay dos componentes. El recorrido DFS pudo llegar a 4 por una ruta de tres aristas, pero existe la arista directa 1−4. DFS sirve para alcanzabilidad; su primera ruta no garantiza distancia mínima. BFS coloca 2 y 4 en la primera capa y descubre 3 en la segunda.'},{title:'Conectar clubes',prompt:'Lee n,m y m conexiones no dirigidas entre clubes numerados de 1 a n. Imprime cuántos grupos de clubes quedan conectados internamente. Un club aislado forma su propio grupo. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000. Se permiten conexiones repetidas.',hints:['Inicia una nueva BFS cada vez que encuentres un club sin visitar.', 'Marca al agregar a la cola.'],solution:'Una BFS desde un club visita exactamente su componente: nunca sale de ella porque sigue aristas, y alcanza todos sus vértices porque existe un camino. Al arrancar solamente desde no visitados, contamos cada componente una vez. Listas de vecinos y cola mantienen O(n+m) tiempo y memoria. Las conexiones repetidas se inspeccionan, pero no duplican visitas.',tests:[{input:'6 3\n1 2\n2 3\n4 5\n',output:'3\n'},{input:'1 0\n',output:'1\n'},{input:'3 4\n1 2\n1 2\n2 3\n3 1\n',output:'1\n'}]});

add('flood-fill',[
 {title:'Convertir celdas en un grafo implícito',body:'No hace falta guardar una lista de adyacencia de todas las casillas. Desde (f,c), genera candidatos (f−1,c),(f+1,c),(f,c−1),(f,c+1). Antes de leer el tablero verifica que la fila y columna estén dentro de sus límites; después comprueba que la celda sea transitable y no esté visitada. El orden de estas comprobaciones importa para evitar accesos inválidos. Un punto puede representar espacio libre y # una pared. Una cola de pares permite ejecutar BFS directamente sobre coordenadas.'},
 {title:'Vecindad es parte del enunciado',body:'En el tablero de dos filas .# y #., las dos celdas libres forman dos regiones si solo puedes moverte en cuatro direcciones. Si se permiten diagonales, forman una. No decidas por la apariencia del dibujo; lee qué movimientos están permitidos. Lo mismo ocurre con bordes que se conectan al otro lado, puertas de un solo sentido o celdas que cambian con el tiempo: el grafo implícito cambia. Flood fill normal solo resuelve un tablero estático con la conectividad que hayas definido.'},
 {title:'Área y perímetro se cuentan distinto',body:'El área es la cantidad de celdas visitadas en la región. Para su perímetro, examina los cuatro lados de cada celda y suma uno si ese lado toca una pared o sale del tablero. Un lado entre dos celdas libres no aporta perímetro, aunque la vecina ya esté visitada. En un bloque libre 2×3, el área es 6 y el perímetro 10. Si cuentas «vecino no visitado» como frontera, el resultado dependerá del orden del recorrido y será incorrecto: visitado es un dato del algoritmo, no una propiedad geométrica.'},
 {title:'Costo y prevención de desbordes de pila',body:'Con F filas y C columnas, cada celda libre entra una sola vez a la cola y examina cuatro vecinos. El tiempo es O(FC) y la memoria puede ser O(FC). Una región enorme puede hacer que DFS recursiva alcance cientos de miles de llamadas; usa cola o pila explícita. Puedes marcar cambiando el carácter del tablero cuando no necesites conservarlo, pero no debes perder información que luego usarás para medir perímetros. Prueba tableros completamente bloqueados, completamente libres, de una fila y con regiones que tocan todos los bordes.'},
],{title:'Una isla con un hueco',prompt:'Un tablero 3×3 tiene todas las celdas libres salvo el centro. Con conectividad de cuatro direcciones, encuentra cantidad de regiones, área y perímetro. Explica por qué el hueco central también cuenta para el perímetro.',hints:['Puedes rodear el centro siguiendo el borde.', 'Cuenta lados que tocan el exterior y lados que tocan el centro.'],solution:'Hay una región de área 8. El borde exterior aporta 12 lados y el hueco central aporta otros 4: perímetro 16. El perímetro cuenta toda frontera entre libre y bloqueado, no solamente el contorno exterior. Ninguna celda diagonal se necesita para conectar la región: el anillo tiene conexiones horizontales y verticales. Esta prueba también detecta implementaciones que cuentan celdas fronterizas en lugar de lados.'},{title:'Salones comunicados',prompt:'Lee F,C y F cadenas de C caracteres, punto para libre y # para pared. Imprime el número de regiones de puntos conectados por arriba, abajo, izquierda o derecha. Límites: 1 ≤ F,C ≤ 800.',hints:['Cada punto sin visitar inicia una nueva región.', 'Marca la celda en cuanto la agregues a la cola.'],solution:'Recorremos todas las celdas. Cuando aparece un punto, iniciamos BFS y cambiamos cada punto descubierto por #. Esta modificación marca visitados; aquí no necesitamos conservar paredes originales porque solo contamos regiones. Las cuatro direcciones generan las únicas conexiones válidas. Cada celda se procesa una vez: O(FC) tiempo y memoria.',code:"#include <iostream>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<string> a(n);\n    for (auto &s : a)\n        cin >> s;\n    int ans = 0, dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n    for (int r = 0; r < n; r++)\n        for (int c = 0; c < m; c++)\n            if (a[r][c] == '.') {\n                ans++;\n                queue<pair<int, int>> q;\n                q.push({r, c});\n                a[r][c] = '#';\n                while (!q.empty()) {\n                    auto [x, y] = q.front();\n                    q.pop();\n                    for (int k = 0; k < 4; k++) {\n                        int u = x + dr[k], v = y + dc[k];\n                        if (u >= 0 && u < n && v >= 0 && v < m && a[u][v] == '.') {\n                            a[u][v] = '#';\n                            q.push({u, v});\n                        }\n                    }\n                }\n            }\n    cout << ans << \"\\n\";\n}",tests:[{input:'3 3\n...\n.#.\n...\n',output:'1\n'},{input:'1 1\n#\n',output:'0\n'},{input:'2 2\n.#\n#.\n',output:'2\n'}]});

add('intro-tree',[
 {title:'Las propiedades equivalentes que debes comprobar',body:'Un árbol no dirigido es un grafo conectado sin ciclos. Con n vértices tiene exactamente n−1 aristas. También puedes reconocerlo como un grafo conectado de n−1 aristas, o uno sin ciclos con n−1 aristas. Tener solamente n−1 aristas no basta: un triángulo y un vértice aislado tienen cuatro vértices y tres aristas, pero no forman un árbol. Entre dos vértices de un árbol hay un único camino simple. Si hubiera dos, sus primeras divergencia y reunión formarían un ciclo.'},
 {title:'Poner una raíz no cambia las aristas',body:'Elegir raíz convierte el camino desde ella en una jerarquía. El padre de v es el vecino anterior en ese camino; los otros vecinos son sus hijos. La profundidad cuenta aristas hasta la raíz. El subárbol de v contiene v y sus descendientes. En las aristas 1−2,1−3,3−4,3−5 con raíz 1, el padre de 4 es 3, su profundidad es 2 y el subárbol de 3 contiene {3,4,5}. Si cambias la raíz a 4, cambian padres y subárboles, pero el camino entre 2 y 5 sigue siendo el mismo.'},
 {title:'Procesar hijos antes que padres',body:'Para calcular tamaño[v], empieza con uno por el propio v y suma tamaño[hijo]. Necesitas que los hijos ya estén resueltos. Un recorrido genera una lista donde cada padre aparece antes que sus hijos; recorrer esa lista al revés invierte la dependencia. En el ejemplo, las hojas 2,4,5 valen 1; luego tamaño[3]=1+1+1=3 y tamaño[1]=1+1+3=5. La fórmula es válida porque los subárboles de hijos distintos no comparten vértices y juntos contienen exactamente los descendientes del padre.'},
 {title:'Distancias y diámetro',body:'El diámetro es la mayor distancia entre dos vértices. En un árbol sin pesos, un BFS desde cualquier vértice encuentra un extremo de algún diámetro; otro BFS desde ese extremo encuentra el otro y su longitud. La unicidad de caminos es esencial para este resultado. No confundas diámetro con altura respecto a una raíz arbitraria: en una estrella de cinco vértices con raíz en el centro, la altura es 1 y el diámetro 2. Para árboles muy profundos usa recorridos iterativos. Una estrella, una cadena y un solo vértice detectan diferentes errores de implementación.'},
],{title:'Cambia la raíz a mano',prompt:'El árbol tiene aristas 1−2,1−3,3−4,3−5. Con raíz 1, da el tamaño de cada subárbol y el diámetro. Después usa raíz 3 y vuelve a dar los tamaños. ¿Cambió el diámetro?',hints:['Cada tamaño incluye al propio vértice.', 'Cambiar la raíz cambia la orientación, no los caminos.'],solution:'Con raíz 1 los tamaños para 1,2,3,4,5 son [5,1,3,1,1]. El diámetro mide 3, por ejemplo 2−1−3−4. Con raíz 3, el vértice 1 tiene hijo 2 y tamaño 2; la raíz contiene todo. Los tamaños son [2,1,5,1,1]. El diámetro sigue siendo 3 porque ninguna arista ni distancia cambió. Raíz es una decisión para organizar el cálculo, no una transformación del grafo.'},{title:'Equipos bajo una coordinación',prompt:'Lee n y n−1 aristas de un árbol con vértices de 1 a n. Usa raíz 1. Imprime para cada vértice, en orden, la cantidad de vértices de su subárbol incluyéndolo. Límites: 1 ≤ n ≤ 200000. La entrada garantiza un árbol.',hints:['Guarda padres y un orden de visita.', 'Recorre el orden al revés y acumula cada tamaño en su padre.'],solution:'Al construir el orden, el padre se agrega antes de que sus hijos puedan agregarse. Por tanto, al recorrer al revés todos los descendientes ya contribuyeron. Inicializamos cada tamaño en 1 y agregamos tamaño[v] al padre. Un árbol permite ignorar la arista de regreso al padre sin usar otra marca. El procedimiento es iterativo y cuesta O(n) tiempo y memoria.',code:"#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), order{0}, sz(n, 1);\n    for (int i = 0; i < n; i++) {\n        int v = order[i];\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                order.push_back(u);\n            }\n    }\n    for (int i = n - 1; i > 0; i--) {\n        int v = order[i];\n        sz[p[v]] += sz[v];\n    }\n    for (int x : sz)\n        cout << x << \" \";\n    cout << \"\\n\";\n}",tests:[{input:'5\n1 2\n1 3\n3 4\n3 5\n',output:'5 1 3 1 1\n'},{input:'1\n',output:'1\n'},{input:'4\n1 2\n2 3\n3 4\n',output:'4 3 2 1\n'}]});

add('func-graphs',[
 {title:'Una salida por vértice cambia la estructura',body:'En un grafo funcional cada vértice tiene exactamente una arista saliente, dada por una función siguiente[v]. Puede apuntar a sí mismo y varios vértices pueden apuntar al mismo destino. Si sigues aristas durante n+1 visitas, algún vértice se repite. Desde esa repetición recorrerás el mismo ciclo indefinidamente porque no hay decisiones. Cada componente débil consta de un ciclo dirigido con árboles de caminos que desembocan en él. Puede haber muchos ciclos en todo el grafo, pero una trayectoria desde un origen llega a uno solo.'},
 {title:'Registrar la primera visita resuelve cola y ciclo',body:'Para siguiente=[2,3,4,3] en numeración desde 1 y origen 1, la trayectoria es 1,2,3,4,3,… Guarda primera[v], inicialmente −1, con el paso de su primera aparición. Registramos primera[1]=0,primera[2]=1,primera[3]=2,primera[4]=3. Cuando regresa 3 en el paso 4, la cola tiene longitud 2 y el ciclo 4−2=2. La lista de orden [1,2,3,4] contiene todas las visitas antes de la primera repetición. No confundas cantidad de vértices distintos con cantidad de movimientos: en el paso cero ya estás en el origen.'},
 {title:'Saltos enormes con una reducción modular',body:'Si k es menor que la longitud de la lista, la respuesta es orden[k]. Si ya alcanzó el ciclo, resta la longitud de la cola μ y toma módulo la longitud del ciclo λ: índice=μ+(k−μ)%λ. En el ejemplo, para k=10, índice=2+(10−2)%2=2 y la respuesta es 3. Simular diez pasos también lo confirma, pero la fórmula sirve para 10 elevado a 18. Usa enteros de 64 bits para k y calcula el módulo únicamente después de comprobar que k≥μ.'},
 {title:'Floyd y saltos binarios: dos alternativas',body:'Floyd mueve una tortuga un paso y una liebre dos, hasta que se encuentran. Luego reinicia una al origen y mueve ambas un paso: se encuentran en la entrada al ciclo. Recorriendo el ciclo puedes medir λ. Usa memoria O(1), pero reconstruir muchas posiciones resulta menos directo. Para muchas consultas de k pasos desde distintos orígenes, precalcula salto[j][v]=salto[j−1][salto[j−1][v]], que representa 2 elevado a j movimientos. Responder según los bits de k cuesta O(log k), con O(n log k) preparación y memoria. Elige según cantidad de consultas, no solo según tamaño de k.'},
],{title:'Cuenta pasos con cuidado',prompt:'Para siguiente=[2,3,4,3], origen 1, encuentra las posiciones después de 0,1,2,3,4 y 101 pasos. Da μ y λ. ¿Qué ocurre si siguiente[1]=1 y empiezas en 1?',hints:['El primer vértice de la lista corresponde a cero movimientos.', 'Reduce solamente los movimientos posteriores a entrar en el ciclo.'],solution:'Las posiciones son 1,2,3,4,3 y 4, respectivamente. La cola 1,2 tiene μ=2; el ciclo 3,4 tiene λ=2. Para 101: 2+(101−2)%2=3, índice de 4. Un lazo 1→1 tiene μ=0 y λ=1: después de cualquier cantidad de pasos permaneces en 1. Este caso obliga a no confundir un ciclo de longitud uno con ausencia de ciclo.'},{title:'Mensajero automático',prompt:'Lee n,s,k y los n destinos siguiente[1],…,siguiente[n]. Empieza en s y sigue exactamente k aristas. Imprime el vértice final. Límites: 1 ≤ n ≤ 200000; 1 ≤ s,siguiente[i] ≤ n; 0 ≤ k ≤ 1000000000000000000.',hints:['Guarda el paso en que visitaste cada vértice.', 'La parte repetida es un ciclo; no simules k movimientos.'],solution:'Seguimos la trayectoria hasta repetir un vértice, en a lo sumo n+1 visitas. La primera posición del repetido marca μ y la diferencia con el tamaño de la lista marca λ. Si k todavía pertenece a la lista se consulta directamente; de lo contrario se reduce al ciclo. El costo es O(n) tiempo y memoria, independiente del tamaño numérico de k.',code:"#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, s;\n    long long k;\n    cin >> n >> s >> k;\n    --s;\n    vector<int> nxt(n), first(n, -1), order;\n    for (int &x : nxt) {\n        cin >> x;\n        --x;\n    }\n    int v = s;\n    while (first[v] == -1) {\n        first[v] = order.size();\n        order.push_back(v);\n        v = nxt[v];\n    }\n    long long mu = first[v], len = order.size() - mu;\n    long long pos = k < (long long)order.size() ? k : mu + (k - mu) % len;\n    cout << order[pos] + 1 << \"\\n\";\n}",tests:[{input:'4 1 101\n2 3 4 3\n',output:'4\n'},{input:'1 1 1000000000000000000\n1\n',output:'1\n'},{input:'3 2 0\n2 3 1\n',output:'2\n'}]});

add('intro-bitwise',[
 {title:'Leer una máscara como un conjunto',body:'El bit i representa si el elemento i está presente. Con n=4, la máscara decimal 10 es binario 1010: contiene los elementos 1 y 3, porque los bits se numeran desde la derecha empezando en cero. Hay 2 elevado a n máscaras, incluyendo cero para el conjunto vacío. La expresión 1ULL<<i construye una máscara con solo el bit i encendido. Usa un tipo sin signo y no desplaces por una cantidad igual o mayor al número de bits del tipo: esas operaciones no tienen el resultado que quizá imaginas.'},
 {title:'Operaciones de conjuntos y operaciones lógicas',body:'A&B conserva bits presentes en ambos conjuntos; A|B reúne los de cualquiera; A^B conserva los que aparecen en exactamente uno. Para agregar i usa A|=(1ULL<<i); para quitarlo A&=~(1ULL<<i); para alternarlo A^=(1ULL<<i). El operador ~ invierte todos los bits del tipo, no solo los n que interesan. Para complementar dentro del universo de n elementos, aplica (~A)&((1ULL<<n)−1), suponiendo n<64. No confundas & con &&: el segundo convierte sus operandos en verdadero o falso y produce un resultado lógico.'},
 {title:'Dos identidades que puedes comprobar',body:'Si x>0, x&(x−1) apaga su bit encendido menos significativo. Por ejemplo 12 es 1100; 11 es 1011; su AND es 1000. Repetir hasta cero cuenta bits en tantas vueltas como unos haya. Para una máscara fija, los subconjuntos se enumeran con s=(s−1)&mask, empezando en mask y tratando cero al final. Sobre mask=1010 aparecen 1010,1000,0010,0000. El AND descarta cualquier bit que no pertenezca al conjunto original. Detén el ciclo después de procesar cero, porque una resta adicional en un entero sin signo vuelve a un valor grande.'},
 {title:'El tamaño de una búsqueda exponencial',body:'Con n=20 hay 1048576 máscaras, cantidad razonable para una operación pequeña por máscara. Con n=40 hay más de un billón, ya no. Si revisas los n bits por máscara, el costo es O(n·2 elevado a n), no solamente O(2 elevado a n). Las máscaras son una forma compacta de representar estados; no eliminan por sí mismas la explosión de posibilidades. En programación dinámica guardarás una respuesta por subconjunto; en encuentro a mitad dividirás las decisiones. Antes de programar, escribe el máximo n y estima la cantidad real de estados.'},
],{title:'Opera sin computadora primero',prompt:'En un universo de cinco elementos, A={0,2,4} y B={1,2,4}. Da sus máscaras decimales, intersección, unión, diferencia simétrica y complemento de A dentro del universo. ¿Cuántos subconjuntos tiene A?',hints:['Los pesos de los bits son 1,2,4,8,16.', 'El complemento necesita limitarse a los cinco bits.'],solution:'A=1+4+16=21 y B=2+4+16=22. A&B=20 representa {2,4}; A|B=23 representa {0,1,2,4}; A^B=3 representa {0,1}. El universo es 31, por lo que el complemento es 31 XOR 21=10, que representa {1,3}. A tiene tres elementos y, por tanto, 8 subconjuntos. El número de elementos se obtiene contando bits, no leyendo el valor decimal de la máscara.'},{title:'Comités de tamaño fijo',prompt:'Lee n,k. Entre n estudiantes distintos, cuenta los subconjuntos de exactamente k integrantes. Usa máscaras para practicar la representación. Límites: 0 ≤ n ≤ 20 y 0 ≤ k ≤ n. Imprime el conteo exacto, incluyendo el comité vacío si k=0.',hints:['Enumera máscaras desde cero hasta 2 elevado a n menos uno.', 'Cuenta los bits encendidos de cada máscara.'],solution:'Cada subconjunto corresponde a una máscara única y cada máscara a un subconjunto. Por eso enumerarlas no omite ni duplica comités. Contamos sus bits y sumamos uno si hay k. La solución tarda O(n·2 elevado a n) y O(1) memoria adicional. La combinatoria de Oro permitirá calcular el mismo valor mucho más rápido; aquí la meta es entender el modelo binario.',tests:[{input:'5 2\n',output:'10\n'},{input:'0 0\n',output:'1\n'},{input:'4 4\n',output:'1\n'}]});

add('silver-conclusion',[
 {title:'Lee los límites como pistas verificables',body:'Un problema que pide conectividad en una cuadrícula sugiere un recorrido, pero puede contener otra decisión: elegir el nivel de agua mínimo que conecta dos puntos. Si n y m permiten visitar todo el tablero, una BFS por nivel candidato es viable. Si el nivel tiene hasta mil millones de valores posibles, probarlos todos no lo es. La condición «existe un camino usando celdas de altura a lo sumo H» es monótona: un camino válido sigue disponible al subir H. Esa combinación produce búsqueda binaria con BFS.'},
 {title:'Diseño del predicado completo',body:'Dado H, primero verifica que origen y destino no superen H. Marca el origen y recorre solamente vecinos dentro del tablero, no visitados y de altura a lo sumo H. Devuelve verdadero si alcanzas el destino. Cada evaluación necesita marcas nuevas; reutilizar sin limpiar visitas de otro H mezclaría dos grafos distintos. Los límites de búsqueda pueden ser el máximo de las alturas de los extremos y la mayor altura del tablero. La segunda cota siempre permite un camino en un tablero rectangular sin otras paredes.'},
 {title:'Caso trabajado de principio a fin',body:'Para alturas [[1,8,2],[2,3,4]], viajar de la esquina superior izquierda a la inferior derecha exige al menos nivel 4 porque el destino tiene altura 4. Con H=4, el camino baja a 2, avanza a 3 y llega a 4: funciona. La celda 8 no importa porque no todas las celdas deben quedar accesibles. El mínimo es 4. En [[1,9],[9,2]], los extremos permiten empezar desde 2, pero ambos primeros movimientos requieren 9. El mínimo es 9. Estos casos distinguen el máximo global del máximo necesario sobre un camino.'},
 {title:'Una revisión que sí detecta errores',body:'Separa cuatro afirmaciones: qué representa H, por qué el recorrido comprueba exactamente su viabilidad, por qué esa viabilidad es monótona y por qué las cotas contienen una respuesta. Para F×C celdas y alturas hasta A, el costo es O(FC log A), con O(FC) memoria. Después de resolver, intenta un tablero de una sola celda y alturas todas iguales. Si no puedes explicar un fallo sin cambiar muchas partes a la vez, prueba primero el predicado de forma aislada. Saber combinar técnicas significa poder justificar cada pieza y sus conexiones.'},
],{title:'Selecciona y descarta técnicas',prompt:'Quieres encontrar el nivel mínimo para conectar esquinas en [[1,7,2],[3,4,5]]. Alguien propone ordenar las alturas y sumar prefijos. Explica qué información falta en esa propuesta y da el nivel óptimo con un camino que lo certifique.',hints:['Una lista ordenada pierde la ubicación de cada celda.', 'El destino impone una cota inferior.'],solution:'La suma de alturas no describe qué celdas son vecinas. Ordenar sin conservar coordenadas pierde la conectividad, por lo que los prefijos no pueden decidir si existe un camino. El destino tiene altura 5, así que H≥5. Con H=5 usamos 1→3→4→5 por la fila inferior; luego 5 es óptimo. Una cota inferior junto con una construcción que la alcanza constituye una prueba completa para este caso.'},{title:'Cruzar el terreno',prompt:'Lee F,C y una matriz de alturas. Puedes moverte horizontal o verticalmente por celdas cuya altura sea a lo sumo H. Imprime el menor H que permite ir de (0,0) a (F−1,C−1). Límites: 1 ≤ F,C ≤ 200; 0 ≤ altura ≤ 1000000000. No hay paredes adicionales.',hints:['Comprueba un nivel con BFS.', 'Subir el nivel nunca elimina un camino disponible.'],solution:'Buscamos la primera altura viable entre el máximo de los extremos y el máximo del tablero. Cada predicado BFS recorre exactamente la componente del origen dentro del conjunto permitido. La viabilidad es monótona y la cota superior permite todas las celdas, por lo que la búsqueda encuentra el mínimo. El costo es O(FC log A) y la memoria O(FC).',code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> a(n, vector<int>(m));\n    int hi = 0;\n    for (auto &r : a)\n        for (int &x : r) {\n            cin >> x;\n            hi = max(hi, x);\n        }\n    int lo = max(a[0][0], a[n - 1][m - 1]);\n    auto ok = [&](int h) {\n        vector<vector<bool>> seen(n, vector<bool>(m));\n        queue<pair<int, int>> q;\n        q.push({0, 0});\n        seen[0][0] = true;\n        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n        while (!q.empty()) {\n            auto [r, c] = q.front();\n            q.pop();\n            if (r == n - 1 && c == m - 1)\n                return true;\n            for (int z = 0; z < 4; z++) {\n                int x = r + dr[z], y = c + dc[z];\n                if (x >= 0 && x < n && y >= 0 && y < m && !seen[x][y] && a[x][y] <= h) {\n                    seen[x][y] = true;\n                    q.push({x, y});\n                }\n            }\n        }\n        return false;\n    };\n    while (lo < hi) {\n        int mid = lo + (hi - lo) / 2;\n        if (ok(mid))\n            hi = mid;\n        else\n            lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n}",tests:[{input:'2 3\n1 8 2\n2 3 4\n',output:'4\n'},{input:'1 1\n7\n',output:'7\n'},{input:'2 2\n1 9\n9 2\n',output:'9\n'}]});

export const silverExpansions = result;
